package com.servicerca.service; import com.servicerca.dto.report.*;import com.servicerca.model.*;import com.servicerca.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReportService{private final ReportRepository reports;private final UserRepository users;private final ServiceRequestRepository requests;public ReportService(ReportRepository r,UserRepository u,ServiceRequestRepository s){reports=r;users=u;requests=s;}@Transactional public ReportResponse create(User reporter,CreateReportRequest body){var x=reports.save(Report.builder().reporter(reporter).reportedUser(users.findById(body.reportedUserId()).orElseThrow()).request(body.requestId()==null?null:requests.findById(body.requestId()).orElseThrow()).reason(body.reason()).details(body.details()).build());return new ReportResponse(x.getId(),x.getReportedUser().getId(),x.getRequest()==null?null:x.getRequest().getId(),x.getReason(),x.getDetails(),x.getCreatedAt());}}
